/* One locked company invoice per job. Existing split-invoice records are retained. */
async function saveSingleJobInvoice(jid,data){const j=getJob(jid);if(!j||role!=='sevlink'||j.callout)return false;if(j.invoices.length>1)return paymentSaveError('This older job has separate invoices. Keep those records and record payments against their existing numbers.');const existing=j.invoices[0],total=approvedQuoteTotal(j);if(total<=0)return paymentSaveError('Approve the quote before invoicing this repair.');const remaining=fromCash(Math.max(0,cash(total)-cash(existing?invoicePaid(existing):0))),deposit=j.status!=='Completed'&&depositSummary(j).outstanding>0,requested=data.requestedAmount==null?(deposit?Math.min(remaining,depositSummary(j).outstanding):remaining):Number(data.requestedAmount);if(!Number.isFinite(requested)||requested<0||cash(requested)>cash(remaining))return paymentSaveError('Enter a request amount between R0.00 and the remaining job balance of '+money(remaining)+'.');data={...data,requestedAmount:requested,requestType:deposit?'Deposit':'Balance',requestedAt:now()};if(!validDate(data.issueDate)||!validDate(data.dueDate)||data.dueDate<data.issueDate)return paymentSaveError('Enter valid invoice and due dates. The due date cannot be before the invoice date.');if(!existing){if(!data.file)return paymentSaveError('Attach the full job invoice document.');return addCompanyInvoice(jid,{...data,amount:total,purpose:'Full',quoteIds:j.quotes.filter(q=>q.status==='Approved').map(q=>q.id)})}if(data.number!==existing.number)return paymentSaveError('The invoice number is locked to '+existing.number+'.');if(cash(existing.amount)!==cash(total)&&!data.file)return paymentSaveError('Upload a revised full invoice for '+money(total)+'. The previous document will remain in the version history.');if(cash(total)<cash(invoicePaid(existing)))return paymentSaveError('The revised total is below payments already received. Review the job records first.');return await commit(()=>{if(data.file){existing.versions??=[];existing.versions.push({number:existing.number,amount:existing.amount,file:existing.file,issueDate:existing.issueDate,dueDate:existing.dueDate,archivedAt:now()});existing.file=data.file}existing.amount=total;existing.purpose='Full';existing.requestHistory??=[];if(existing.requestedAmount!=null)existing.requestHistory.push({amount:existing.requestedAmount,type:existing.requestType,at:existing.requestedAt});existing.requestedAmount=requested;existing.requestType=data.requestType;existing.requestedAt=now();existing.issueDate=data.issueDate;existing.dueDate=data.dueDate;existing.billTo=data.billTo;existing.email=data.email;j.companyInvoiceNumber=existing.number;if(j.status==='Completed')j.finalInvoiceRecorded=true;financialAudit(j,'Invoice '+existing.number+' reviewed under the same locked number. Total '+money(total)+', verified receipts '+money(invoicePaid(existing))+'. '+data.requestType+' amount requested now: '+money(requested)+'. Previous document versions retained.');})?existing:false}
const addInvoiceBeforeNumberLock=addCompanyInvoice;addCompanyInvoice=async function(jid,data){const j=getJob(jid);if(j&&!j.callout&&j.companyInvoiceNumber&&j.invoices.length)return paymentSaveError('Invoice '+j.companyInvoiceNumber+' is already linked to this job. Open it to record payments or upload a revised document.');const result=await addInvoiceBeforeNumberLock(jid,data);if(result){const job=getJob(jid);if(job?.invoices.length===1)await commit(()=>job.companyInvoiceNumber=result.number)}return result};
const invoiceFormBeforeSingle=invoiceForm;invoiceForm=function(jid){const j=getJob(jid);if(!j||role!=='sevlink')return;if(j.callout||approvedQuoteTotal(j)<=0)return invoiceFormBeforeSingle(jid);if(j.invoices.length>1){jobDetail(jid,'invoices');paymentSaveError('This older job already has separate invoices. Their numbers and payments have been preserved.');return}const i=j.invoices[0],a=state.agencies.find(a=>a.id===j.agency),total=approvedQuoteTotal(j),received=i?invoicePaid(i):0,requestDeposit=j.status!=='Completed'&&depositSummary(j).outstanding>0,requestAmount=requestDeposit?Math.min(fromCash(Math.max(0,cash(total)-cash(received))),depositSummary(j).outstanding):fromCash(Math.max(0,cash(total)-cash(received)));openForm(requestDeposit?'Prepare deposit invoice.':'Prepare final balance invoice.',`<div id="paymentSaveError" class="notice" role="alert" hidden></div><div class="notice"><b>One company invoice for the full job</b><p>Full job total: ${money(total)}<br>50% deposit target: ${money(depositSummary(j).required)}<br>Verified payments: ${money(received)}<br><b>Remaining to pay: ${money(fromCash(Math.max(0,cash(total)-cash(received))))}</b></p><p>Request the deposit now and the remaining balance later under this same number. Your manual invoice should show the full job total, payments received, and the amount requested now.</p></div><label>Company invoice number ${i?'· locked':''}</label><input name="number" value="${esc(i?.number||'')}" ${i?'readonly aria-readonly="true"':'required'}><label for="invoiceRequestAmount">${requestDeposit?'Deposit amount requested now':'Balance amount requested now'} (ZAR) · editable</label><input id="invoiceRequestAmount" name="requestedAmount" type="number" min="0" max="${fromCash(Math.max(0,cash(total)-cash(received)))}" step="0.01" required value="${requestAmount.toFixed(2)}" style="font-size:22px;font-weight:750;background:#eef8fc"><small>${requestDeposit?'Automatically starts at the unpaid portion of the 50% deposit. You can adjust this request; the scheduling deposit target remains 50% unless Sevlink authorises an exception.':'Automatically starts at the full job total less verified payments received.'}</small><label>Full job total (ZAR) · retained for the job</label><input value="${total.toFixed(2)}" readonly aria-readonly="true"><label for="remainingInvoiceBalance">Remaining to pay (ZAR) · calculated automatically</label><input id="remainingInvoiceBalance" value="${fromCash(Math.max(0,cash(total)-cash(received))).toFixed(2)}" readonly aria-readonly="true" style="font-size:22px;font-weight:750;color:#075b94;background:#eef8fc"><p>Show the full total, payments already received, and this remaining amount on your manually prepared invoice. Keep the same invoice number.</p><div class="row"><div>${field('Invoice date','issueDate',i?.issueDate||todayKey(),'date')}</div><div>${field('Due date','dueDate',i?.dueDate||todayKey(),'date')}</div></div>${field('Bill to','billTo',i?.billTo||a.name)}${field('Recipient email','email',i?.email||a.email,'email')}<label>${i?'Revised full invoice document (required if the old invoice covered only part of the job)':'Full job invoice document (required)'}</label><input name="file" type="file" ${!i||cash(i.amount)!==cash(total)?'required':''} accept="application/pdf,image/jpeg,image/png,image/webp"><p>PDF or image, up to 5 MB. An uploaded revision keeps the old document in the invoice history. No email is sent by this demo.</p>`,i?'Save amount requested':'Save request & lock invoice number',async d=>{let file;try{file=await fileData(d.get('file'),quoteTypes)}catch(e){paymentSaveError(e.message);return}if(await saveSingleJobInvoice(jid,{number:d.get('number'),issueDate:d.get('issueDate'),dueDate:d.get('dueDate'),billTo:d.get('billTo'),email:d.get('email'),requestedAmount:Number(d.get('requestedAmount')),file})){render();jobDetail(jid,'invoices');toast('Invoice saved under the locked company number.')}});$('#form')?.addEventListener?.('invalid',e=>paymentSaveError('Complete the '+(e.target.name==='file'?'full invoice attachment':e.target.name||'required field')+' before saving.'),true)};
const depositPanelBeforeSingle=depositPanel;depositPanel=function(j){return depositPanelBeforeSingle(j).replace(/Upload remaining deposit invoice · [^<]+/g,'Upload / review full job invoice').replace('The previous invoice is settled. Upload a supplementary deposit invoice using its own company invoice number, then record the additional payment.','The earlier invoice covered only part of the job. Upload a revised full invoice using its locked number; earlier versions and payments are retained.')};
const remainingActionBeforeSingle=remainingDepositAction;remainingDepositAction=function(j){return remainingActionBeforeSingle(j).replace(/Upload remaining deposit invoice · [^<]+/g,'Review full invoice / remaining deposit').replace('The previous invoice is settled. Upload a supplementary deposit invoice using its own company invoice number, then record the additional payment.','Review the full invoice under the same locked number, then record the next deposit instalment.')};
const renderInvoicesBeforeVersions=renderInvoices;renderInvoices=function(j){renderInvoicesBeforeVersions(j);if(role==='tenant')return;for(const i of j.invoices){if(i.requestedAmount!=null)$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>${esc(i.number)} · ${esc(i.requestType||'Payment')} requested: ${money(i.requestedAmount)}</b><p>Full job invoice total: ${money(i.amount)} · Verified received: ${money(invoicePaid(i))} · Remaining: ${money(invoiceBalance(i))}</p></div>`);if(i.versions?.length)$('#jobcontent').insertAdjacentHTML('beforeend',`<details class="card"><summary>${esc(i.number)} · Previous invoice document versions (${i.versions.length})</summary>${i.versions.map((v,n)=>`<p>${money(v.amount)} · ${date(v.archivedAt)} <button class="secondary" onclick="downloadInvoiceVersion('${j.id}','${i.id}',${n})">Download previous document</button></p>`).join('')}</details>`)}};
function downloadInvoiceVersion(jid,iid,index){const i=findInvoice(jid,iid);if(role!=='tenant'&&i?.versions?.[index]?.file)download(i.versions[index].file)}


const normaliseBeforeInvoiceLock=normalise;normalise=function(){normaliseBeforeInvoiceLock();for(const j of state.jobs)if(j.invoices.length===1)j.companyInvoiceNumber??=j.invoices[0].number};
const paymentFormBeforeSingle=paymentForm;paymentForm=function(jid,iid){paymentFormBeforeSingle(jid,iid);const j=getJob(jid),i=findInvoice(jid,iid);if(!j||!i)return;const amount=modal.querySelector('input[name="amount"]'),purpose=modal.querySelector('select[name="purpose"]');if(!j.callout&&j.status!=='Completed'&&depositSummary(j).outstanding>0){if(amount)amount.value=Math.min(invoiceBalance(i),depositSummary(j).outstanding);if(purpose)purpose.value='Deposit'}else if(purpose)purpose.value='Balance'};
const balanceSummaryBeforeSingle=jobBalanceSummary;jobBalanceSummary=function(j){if(j.invoices.length<=1&&!j.callout&&approvedQuoteTotal(j)>0&&role!=='tenant'){const total=approvedQuoteTotal(j),paid=depositSummary(j).received;return `<div class="notice"><b>Full job balance · ${esc(j.invoices[0]?.number||'invoice not uploaded')}</b><p>Full job: ${money(total)}<br>Verified received: ${money(paid)}<br><b>Still to pay: ${money(fromCash(Math.max(0,cash(total)-cash(paid))))}</b></p><p>Deposit and final payments stay on the same locked invoice number.</p></div>`}return balanceSummaryBeforeSingle(j)};

